# System.Runtime.Intrinsics.X86.Avx — bitwise operations on the float lanes. AndNot is
# VANDNPS / VANDNPD: the complement of the FIRST operand, so the portable AndNot's operands
# swap.
target = avx
And(v256{T},v256{T}) @ref(Vector256.BitwiseAnd($0, $1)) = _mm256_and_{ps|pd}($0, $1) for T in f32,f64
AndNot(v256{T},v256{T}) @ref(Vector256.AndNot($1, $0)) = _mm256_andnot_{ps|pd}($0, $1) for T in f32,f64
Or(v256{T},v256{T}) @ref(Vector256.BitwiseOr($0, $1)) = _mm256_or_{ps|pd}($0, $1) for T in f32,f64
Xor(v256{T},v256{T}) @ref(Vector256.Xor($0, $1)) = _mm256_xor_{ps|pd}($0, $1) for T in f32,f64
